package greeter

import "strings"

// Slug 把一段文本转成 URL 友好的片段：统一转小写，去掉首尾空白，
// 并把连续空白折成一个连字符。
func Slug(s string) string {
	return strings.Join(strings.Fields(strings.ToLower(s)), "-")
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"Hello World", "hello-world"},
		{"  Hello World  ", "hello-world"},
		{"a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("Slug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 把多个片段各自转成 Slug，再用 "/" 连接；转换后为空的片段被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	cases := []struct {
		parts []string
		want  string
	}{
		{[]string{"Hello World", "Big Day"}, "hello-world/big-day"},
		{[]string{"a", "", "b"}, "a/b"},
		{[]string{"a", "   ", "b"}, "a/b"},
	}
	for _, c := range cases {
		if got := JoinSlug(c.parts...); got != c.want {
			t.Errorf("JoinSlug(%q) = %q, want %q", c.parts, got, c.want)
		}
	}
}
